CREATE TABLE restaurant_cms(restaurant_id text PRIMARY KEY REFERENCES restaurants,draft jsonb,draft_revision integer NOT NULL DEFAULT 0 CHECK(draft_revision>=0),draft_updated_at timestamptz,draft_updated_by text,published_version_id text,settings jsonb NOT NULL DEFAULT '{}');
CREATE TABLE cms_versions(id text PRIMARY KEY,restaurant_id text NOT NULL REFERENCES restaurants,number integer NOT NULL CHECK(number>0),schema_version integer NOT NULL,config jsonb NOT NULL,summary text NOT NULL DEFAULT '',restored_from integer,published_by text,published_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(restaurant_id,number),UNIQUE(restaurant_id,id));
ALTER TABLE restaurant_cms ADD FOREIGN KEY(restaurant_id,published_version_id) REFERENCES cms_versions(restaurant_id,id);
CREATE TABLE cms_media(id text PRIMARY KEY,restaurant_id text NOT NULL REFERENCES restaurants,kind text NOT NULL CHECK(kind IN ('image','video')),file text NOT NULL UNIQUE,mime text NOT NULL,size integer NOT NULL CHECK(size>0),width integer,height integer,alt text NOT NULL DEFAULT '',original_name text NOT NULL DEFAULT '',created_by text,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),archived_at timestamptz);
CREATE INDEX cms_media_scope ON cms_media(restaurant_id,created_at DESC);
ALTER TABLE restaurant_cms ENABLE ROW LEVEL SECURITY;
CREATE POLICY cms_scope ON restaurant_cms USING(app.in_restaurant(restaurant_id)) WITH CHECK(app.in_restaurant(restaurant_id));
ALTER TABLE cms_versions ENABLE ROW LEVEL SECURITY;
CREATE POLICY versions_scope ON cms_versions USING(app.in_restaurant(restaurant_id)) WITH CHECK(app.in_restaurant(restaurant_id));
ALTER TABLE cms_media ENABLE ROW LEVEL SECURITY;
CREATE POLICY media_scope ON cms_media USING(app.in_restaurant(restaurant_id)) WITH CHECK(app.in_restaurant(restaurant_id));
INSERT INTO restaurant_cms(restaurant_id) SELECT id FROM restaurants;
CREATE FUNCTION app.setup_cms() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN INSERT INTO restaurant_cms(restaurant_id) VALUES(NEW.id);RETURN NEW;END $$;
CREATE TRIGGER cms_setup AFTER INSERT ON restaurants FOR EACH ROW EXECUTE FUNCTION app.setup_cms();
DO $$ BEGIN IF NOT EXISTS(SELECT FROM pg_roles WHERE rolname='atacuisine_app') THEN CREATE ROLE atacuisine_app NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOBYPASSRLS; END IF; END $$;
GRANT USAGE ON SCHEMA public,app TO atacuisine_app;
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA public TO atacuisine_app;
GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA public TO atacuisine_app;
GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA app TO atacuisine_app;
REVOKE ALL ON schema_versions FROM atacuisine_app;
REVOKE EXECUTE ON FUNCTION app.claim_jobs(text) FROM atacuisine_app;
INSERT INTO schema_versions VALUES(12);
